package shop.blueroblox.app;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/** Logo cá voi Cloud Blue (ảnh nét, nền trong suốt) nhúng sẵn trong app — không cần thêm file ảnh. */
final class Brand {
    private static Bitmap whale;
    static Bitmap whale() {
        if (whale == null) {
            byte[] b = Base64.decode(W, Base64.DEFAULT);
            whale = BitmapFactory.decodeByteArray(b, 0, b.length);
        }
        return whale;
    }
    private static final String W =
        "" +
        "" +
        "" +
        "" +
        "";
}
